package export

import (
	"archive/zip"
	"bytes"
	"context"
	"encoding/xml"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
	"time"
	"unicode"

	"github.com/gomcpgo/htmltodocx"
	"golang.org/x/net/html"
)

// corpusDir holds HTML documents written by real models through this server
// (generated by Rolltop's TestGenerateDocxCorpus integration test). Each
// subfolder is one document folder: index.html, media/, corpus.yaml.
const corpusDir = "../../testdata/export_corpus"

// lostWordFlag marks a document in the report when more than this share of its
// text is missing from the DOCX. It is a pointer for review, not a failure: the
// extractor below ignores <style> rules, so text that a stylesheet hides (often
// print-only toggles) counts as lost even though dropping it is correct.
const lostWordFlag = 0.01

type corpusResult struct {
	name      string
	err       error
	warnings  []htmltodocx.Warning
	htmlWords int
	lost      []string
	size      int
	elapsed   time.Duration
}

// TestExportCorpusDOCX converts every corpus document with htmltodocx. It fails
// when a conversion fails, and reports warnings and text that went missing.
//
// Optional environment:
//
//	CORPUS_DOCX_OUT  write each .docx here for opening in Word / Docs / LibreOffice
//	CORPUS_REPORT    write a markdown report (warnings by code, lost text) to this file
func TestExportCorpusDOCX(t *testing.T) {
	entries, err := os.ReadDir(corpusDir)
	if err != nil || len(entries) == 0 {
		t.Skipf("no corpus in %s", corpusDir)
	}
	docxOut := os.Getenv("CORPUS_DOCX_OUT")
	if docxOut != "" {
		if err := os.MkdirAll(docxOut, 0o755); err != nil {
			t.Fatal(err)
		}
	}

	var results []corpusResult
	for _, e := range entries {
		dir := filepath.Join(corpusDir, e.Name())
		if _, err := os.Stat(filepath.Join(dir, "index.html")); !e.IsDir() || err != nil {
			continue
		}
		r := convertCorpusDocument(t, e.Name(), dir)
		results = append(results, r)
		if docxOut != "" && r.err == nil {
			// convertCorpusDocument already produced the bytes; re-run is cheap
			// and keeps that function free of output concerns.
			data, _ := convertDir(dir, nil)
			if err := os.WriteFile(filepath.Join(docxOut, e.Name()+".docx"), data, 0o644); err != nil {
				t.Fatal(err)
			}
		}
	}

	for _, r := range results {
		if r.err != nil {
			t.Errorf("%s: %v", r.name, r.err)
			continue
		}
		if r.htmlWords > 0 && float64(len(r.lost))/float64(r.htmlWords) > lostWordFlag {
			t.Logf("REVIEW %s: %d of %d words missing from the DOCX, e.g. %q",
				r.name, len(r.lost), r.htmlWords, firstN(r.lost, 15))
		}
	}

	report := corpusReport(results)
	t.Log("\n" + report)
	if path := os.Getenv("CORPUS_REPORT"); path != "" {
		if err := os.WriteFile(path, []byte(report), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

func convertDir(dir string, warn func(htmltodocx.Warning)) ([]byte, error) {
	src, err := os.ReadFile(filepath.Join(dir, "index.html"))
	if err != nil {
		return nil, err
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	return htmltodocx.ConvertString(ctx, string(src), &htmltodocx.Options{
		Resources: htmltodocx.DirLoader(dir),
		Warn:      warn,
		Created:   time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
	})
}

func convertCorpusDocument(t *testing.T, name, dir string) corpusResult {
	t.Helper()
	r := corpusResult{name: name}
	start := time.Now()
	data, err := convertDir(dir, func(w htmltodocx.Warning) { r.warnings = append(r.warnings, w) })
	r.elapsed = time.Since(start)
	if err != nil {
		r.err = err
		return r
	}
	r.size = len(data)

	src, err := os.ReadFile(filepath.Join(dir, "index.html"))
	if err != nil {
		r.err = err
		return r
	}
	htmlWords := words(visibleHTMLText(string(src)))
	docxText, err := docxBodyText(data)
	if err != nil {
		r.err = fmt.Errorf("reading back the DOCX: %w", err)
		return r
	}
	r.htmlWords = len(htmlWords)
	r.lost = missingWords(htmlWords, words(docxText))
	return r
}

// blockTags end a word at their boundaries, as a browser lays them out.
var blockTags = map[string]bool{
	"address": true, "article": true, "aside": true, "blockquote": true, "br": true, "caption": true,
	"dd": true, "details": true, "div": true, "dl": true, "dt": true, "fieldset": true,
	"figcaption": true, "figure": true, "footer": true, "form": true, "h1": true, "h2": true,
	"h3": true, "h4": true, "h5": true, "h6": true, "header": true, "hr": true, "li": true,
	"main": true, "nav": true, "ol": true, "p": true, "pre": true, "section": true,
	"summary": true, "table": true, "td": true, "th": true, "tr": true, "ul": true,
}

var (
	cssRule       = regexp.MustCompile(`([^{}]+)\{([^{}]*)\}`)
	flexOrGrid    = regexp.MustCompile(`display\s*:\s*(inline-)?(flex|grid)`)
	lastClassName = regexp.MustCompile(`\.([A-Za-z0-9_-]+)\s*$`)
)

// layoutClasses returns the class names that some <style> rule lays out as
// flex or grid. Their children are separate boxes in a browser even when the
// markup has no white space between them. Only selectors ending in a class
// are recognised; that covers what models write.
func layoutClasses(doc *html.Node) map[string]bool {
	var css strings.Builder
	var collect func(n *html.Node)
	collect = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == "style" && n.FirstChild != nil {
			css.WriteString(n.FirstChild.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			collect(c)
		}
	}
	collect(doc)
	classes := map[string]bool{}
	for _, m := range cssRule.FindAllStringSubmatch(css.String(), -1) {
		if !flexOrGrid.MatchString(m[2]) {
			continue
		}
		for _, sel := range strings.Split(m[1], ",") {
			if c := lastClassName.FindStringSubmatch(strings.TrimSpace(sel)); c != nil {
				classes[c[1]] = true
			}
		}
	}
	return classes
}

// visibleHTMLText returns the text a reader would see, split into words the
// way a browser lays them out: inline elements join ("CO<sub>2</sub>" is one
// word), block elements and the children of flex and grid containers do not.
// It skips head, script, style, template, and elements hidden with the hidden
// attribute or an inline display:none. Rules in <style> that hide text are not
// applied, so such text is reported as lost and needs a human look.
func visibleHTMLText(src string) string {
	doc, err := html.Parse(strings.NewReader(src))
	if err != nil {
		return ""
	}
	layout := layoutClasses(doc)
	separatesChildren := func(n *html.Node) bool {
		for _, a := range n.Attr {
			switch a.Key {
			case "style":
				if flexOrGrid.MatchString(strings.ToLower(a.Val)) {
					return true
				}
			case "class":
				for _, c := range strings.Fields(a.Val) {
					if layout[c] {
						return true
					}
				}
			}
		}
		return false
	}

	var b strings.Builder
	var walk func(n *html.Node)
	walk = func(n *html.Node) {
		split := false
		if n.Type == html.ElementNode {
			switch n.Data {
			case "head", "script", "style", "template", "noscript", "title":
				return
			}
			for _, a := range n.Attr {
				if a.Key == "hidden" {
					return
				}
				if a.Key == "style" && strings.Contains(strings.ReplaceAll(strings.ToLower(a.Val), " ", ""), "display:none") {
					return
				}
			}
			split = separatesChildren(n)
			if blockTags[n.Data] {
				b.WriteByte(' ')
				defer b.WriteByte(' ')
			}
		}
		if n.Type == html.TextNode {
			b.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
			if split {
				b.WriteByte(' ')
			}
		}
	}
	walk(doc)
	return b.String()
}

// docxBodyText returns the text of word/document.xml as a reader sees it.
func docxBodyText(docx []byte) (string, error) {
	zr, err := zip.NewReader(bytes.NewReader(docx), int64(len(docx)))
	if err != nil {
		return "", err
	}
	for _, f := range zr.File {
		if f.Name != "word/document.xml" {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return "", err
		}
		defer rc.Close()
		var b strings.Builder
		dec := xml.NewDecoder(rc)
		inText := false
		for {
			tok, err := dec.Token()
			if err == io.EOF {
				return b.String(), nil
			}
			if err != nil {
				return "", err
			}
			switch v := tok.(type) {
			case xml.StartElement:
				inText = v.Name.Local == "t"
				if v.Name.Local == "tab" || v.Name.Local == "br" || v.Name.Local == "cr" {
					b.WriteByte(' ')
				}
			case xml.EndElement:
				// Runs join with no space, as Word shows them, so text the
				// converter glued together ("CoreGo") shows up as lost words.
				// Paragraphs and table cells end a word.
				if v.Name.Local == "p" || v.Name.Local == "tc" {
					b.WriteByte(' ')
				}
				inText = false
			case xml.CharData:
				if inText {
					b.Write(v)
				}
			}
		}
	}
	return "", fmt.Errorf("no word/document.xml")
}

// words splits on anything that is not a letter, digit or mark, so
// punctuation and run boundaries do not matter.
func words(s string) []string {
	return strings.FieldsFunc(strings.ToLower(s), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r) && !unicode.IsMark(r)
	})
}

// missingWords returns the words of want that got does not account for,
// counting repeats.
func missingWords(want, got []string) []string {
	have := map[string]int{}
	for _, w := range got {
		have[w]++
	}
	var lost []string
	for _, w := range want {
		if have[w] > 0 {
			have[w]--
			continue
		}
		lost = append(lost, w)
	}
	return lost
}

func firstN(s []string, n int) []string {
	if len(s) > n {
		return s[:n]
	}
	return s
}

func corpusReport(results []corpusResult) string {
	var b strings.Builder
	fmt.Fprintf(&b, "# DOCX corpus report\n\n%d documents\n\n", len(results))

	// Warnings by code: how many documents hit each, and sample messages.
	type codeStat struct {
		docs     map[string]bool
		count    int
		messages map[string]int
	}
	codes := map[string]*codeStat{}
	for _, r := range results {
		for _, w := range r.warnings {
			s := codes[w.Code]
			if s == nil {
				s = &codeStat{docs: map[string]bool{}, messages: map[string]int{}}
				codes[w.Code] = s
			}
			s.docs[r.name] = true
			s.count++
			s.messages[w.Message]++
		}
	}
	keys := make([]string, 0, len(codes))
	for k := range codes {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return len(codes[keys[i]].docs) > len(codes[keys[j]].docs) })

	b.WriteString("## Warnings by code\n\n| Code | Documents | Count | Most frequent messages |\n|---|---|---|---|\n")
	for _, k := range keys {
		s := codes[k]
		type mc struct {
			m string
			c int
		}
		var ms []mc
		for m, c := range s.messages {
			ms = append(ms, mc{m, c})
		}
		sort.Slice(ms, func(i, j int) bool { return ms[i].c > ms[j].c })
		var top []string
		for i := 0; i < len(ms) && i < 4; i++ {
			top = append(top, fmt.Sprintf("%s (%d)", strings.ReplaceAll(ms[i].m, "|", "\\|"), ms[i].c))
		}
		fmt.Fprintf(&b, "| %s | %d | %d | %s |\n", k, len(s.docs), s.count, strings.Join(top, "; "))
	}

	b.WriteString("\n## Per document\n\n| Document | Result | Words | Lost | Warnings | Size | Time |\n|---|---|---|---|---|---|---|\n")
	for _, r := range results {
		status := "ok"
		if r.err != nil {
			status = "ERROR: " + r.err.Error()
		}
		lost := fmt.Sprintf("%d", len(r.lost))
		if len(r.lost) > 0 {
			lost += fmt.Sprintf(" %q", firstN(r.lost, 6))
		}
		fmt.Fprintf(&b, "| %s | %s | %d | %s | %d | %d KB | %s |\n",
			r.name, status, r.htmlWords, lost, len(r.warnings), r.size/1024, r.elapsed.Round(time.Millisecond))
	}
	return b.String()
}
